pub fn ensure_workflows_attachments(conn: &rusqlite::Connection) -> Result<(), String> {
    // PRAGMA 失败 = 真正的 DB 问题，必须把原始错误透传给 open_db，
    // 不能吞掉后用 ALTER 的副作用错误误导排障。
    let mut stmt = conn
        .prepare("PRAGMA table_info(workflows)")
        .map_err(|e| e.to_string())?;
    let rows = stmt
        .query_map([], |r| r.get::<_, String>(1))
        .map_err(|e| e.to_string())?;
    let has = rows.filter_map(|n| n.ok()).any(|n| n == "attachments");
    if !has {
        conn.execute("ALTER TABLE workflows ADD COLUMN attachments TEXT", [])
            .map_err(|e| e.to_string())?;
    }
    Ok(())
}

